import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.TQKaXlFR.js";const b=JSON.parse('{"title":"版本与配套组合","description":"","frontmatter":{},"headers":[],"relativePath":"releases/versions.md","filePath":"releases/versions.md"}'),o={name:"releases/versions.md"};function i(l,t,n,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="版本与配套组合" tabindex="-1">版本与配套组合 <a class="header-anchor" href="#版本与配套组合" aria-label="Permalink to &quot;版本与配套组合&quot;">​</a></h1><p>本页供部署者和维护者确定文档对应哪份代码、产物和数据库迁移。v1.2.0已发布静态快照；当前源码包含另行验收的AI一期新增能力，但尚未为AI一期建立独立发行Tag。静态版本、源码提交和构建元数据分别记录，不据此声明长期上游支持、企业采用或完整跨版本兼容。</p><h2 id="静态站点发布与应用版本" tabindex="-1">静态站点发布与应用版本 <a class="header-anchor" href="#静态站点发布与应用版本" aria-label="Permalink to &quot;静态站点发布与应用版本&quot;">​</a></h2><p>已发布 Pages 入口为<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/" target="_blank" rel="noreferrer">后台静态演示</a>与<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/docs/" target="_blank" rel="noreferrer">文档</a>。公开仓库同时承载前端源码和审核后的 <code>site/</code>；源码更新不自动重建静态产物。2026-10-17 一期更新重新构建演示与本套文档，展示 AI 独立一级导航及只读虚构示例；模型调用、测试、审批和发布不会在静态站运行。部署结果以<a href="https://github.com/beidaomitu233/xinghui-admin-vue3/actions" target="_blank" rel="noreferrer">公开仓库 Actions</a>和实际HTTP为准。</p><p>静态站点部署提交与下面的应用教程基线分别记录，不能把 demo SHA 当后端版本。Pages 工作流通过不代表应用质量 CI、数据库容器矩阵或正式后端发行通过。</p><h2 id="一期工作区改造-待组合验收" tabindex="-1">一期工作区改造（待组合验收） <a class="header-anchor" href="#一期工作区改造-待组合验收" aria-label="Permalink to &quot;一期工作区改造（待组合验收）&quot;">​</a></h2><p>新操作手册按调用监控和提示词配置两个入口说明，Key设置从监控进入；合法配置直接保存生成不可变执行快照，旧模板按精确基线转换并保留批准范围。后端新增V225；尚未登记改造后的正式前后端配对、发行Tag或部署验收。下面旧基线的通过结果不能代替新工作区的迁移、连续保存、权限和页面组合验收。</p><h2 id="当前源码基线" tabindex="-1">当前源码基线 <a class="header-anchor" href="#当前源码基线" aria-label="Permalink to &quot;当前源码基线&quot;">​</a></h2><p>2026-10-16工作区改造前的一期验收组合：</p><table tabindex="0"><thead><tr><th>仓库</th><th>精确源码提交</th></tr></thead><tbody><tr><td>后端</td><td><code>79b4655b56621fbcdafe48eb858d312bd76eb465</code></td></tr><tr><td>前端</td><td><code>6945d0b80954c2296f567df2840675d51e8874ac</code></td></tr></tbody></table><p>该组合已完成正式CI、组合集成和真实低代码摘要闭环：认证/授权取数、模板与精确发布版本预览、应用发布、真实模型、SSE及请求日志、结果采纳草稿、人工保存和刷新数据库核对。配置/应用/模板/日志属于AI一期；Agent、插件、工具执行、审批写和持久会话尚未实现。HTTP身份仍来自登录用户，后台服务身份接入不能仅凭范围配置视为已完成。</p><p>2026-10-17 Pages 更新在上述一期基线上补齐静态演示与文档，并修复配置、模板和数据引用详情中的只读编辑锁；启用权限与编辑权限继续独立。该静态构建的精确来源记录在<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/publication.json" target="_blank" rel="noreferrer">发布产物清单</a>，本轮代码与合并检查见仓库 Actions。它不加入二期代码，也不改变 v1.2.0 标签。</p><p>工作区改造前的后端API源码盘点为38个Controller、36个有映射、206条方法/路径，其中一期新增6个Controller和59条映射。本次场景工作区另有4个Controller、20条新增映射，该旧盘点不包含这些接口；完整目录与分项权限见<a href="./../reference/api-catalog.html">API目录</a>。迁移按当前源码完整目录执行，包含AI新增V180、V190、V200、V210、V220；不能仅依据下面旧快照的V170或历史行数验收当前环境。</p><p>本次文档修改在该前端提交之上单独提交，不改变后端版本，也不表示上述源码已获得新Tag。供应商失败/限流和未知用量仍如实处理；受控故障用例不冒充真实模型结果。</p><h2 id="v1-2-0静态旧快照的教程基线" tabindex="-1">v1.2.0静态旧快照的教程基线 <a class="header-anchor" href="#v1-2-0静态旧快照的教程基线" aria-label="Permalink to &quot;v1.2.0静态旧快照的教程基线&quot;">​</a></h2><p>以下为2026-10-13核对的旧教程应用组合，用于解释保留的旧API目录及原验证数字，不是当前AI一期源码配对：</p><table tabindex="0"><thead><tr><th>仓库</th><th>精确应用提交</th></tr></thead><tbody><tr><td>后端</td><td><code>5f4746ddabb4bdeb0eaba74f7808d809b277306c</code></td></tr><tr><td>前端</td><td><code>3b6a4141d84b207b5380d667e6100dc585a64d62</code></td></tr></tbody></table><p>后端后续交接文档提交不等于重新编译过的应用源码。文档中心本身由独立文档分支组合，应用入口/文档站配置可能有自己的后续提交；部署时需要一起记录，不能把文档更新写成新业务发行。</p><p>包文件中后端<code>1.1.0-SNAPSHOT</code>、前端派生工作区<code>5.5.9</code>是构建元数据，后者沿用上游包版本，不表示本项目正式版本5.5.9。只有实际项目发布流程产生的Tag/manifest才能作为正式版本记录；仓库URL未配置时不虚构下载或发行链接。</p><h2 id="旧教程基线能力范围" tabindex="-1">旧教程基线能力范围 <a class="header-anchor" href="#旧教程基线能力范围" aria-label="Permalink to &quot;旧教程基线能力范围&quot;">​</a></h2><ul><li>登录/用户角色菜单、平台身份与操作码、字典、参数、文件与受控批量操作。</li><li>安全调度handler与执行诊断、站内通知模板/事件和本人收件箱。</li><li>AI模型元数据、环境/数据库凭据及受控模型测试；多应用场景草稿/发布/变量预览、注册业务上下文的prompt读取接缝。</li><li>微信PC网站授权发起、state/cookie/callback边界；<strong>完整微信绑定登录尚未交付</strong>，无AppID/资格的外部扫码验证暂缓。</li><li>微信/SMS/OSS统一业务配置、加密密钥、revision与历史存储读取；低代码七种字段、发布schema、记录CRUD/冲突与租户范围。</li><li>菜单合并为“系统管理、通用能力、运行维护”，普通登录者保留本人收件箱，中性工作区主题与强调色区分。</li></ul><p>通用资料示例、网站内容管理、下载、页面业务模块已退役；资讯/公告等保留业务仍存在。数据库历史迁移保留退役链路，不代表旧模块仍可用。没有部门/岗位体系、匿名低代码公开填写、附件/复杂联动或两个独立真实业务系统采用证明。</p><h2 id="旧教程基线已验证与未验证" tabindex="-1">旧教程基线已验证与未验证 <a class="header-anchor" href="#旧教程基线已验证与未验证" aria-label="Permalink to &quot;旧教程基线已验证与未验证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前证据与边界</th></tr></thead><tbody><tr><td>后端本地</td><td>JDK17全模块构建，43必需类169项+1真实服务项通过</td></tr><tr><td>数据库</td><td>MySQL8.0.12空库，含V170与optional清理R共23条history，重启strict校验；默认versioned目录22份</td></tr><tr><td>前端本地</td><td>root409、app118、auth4，零失败/跳过；类型、lint与11任务生产构建通过</td></tr><tr><td>lint</td><td>0error、34warning，保留规则；warning不是零警告证明</td></tr><tr><td>供应商</td><td>历史模型测试NVIDIA成功、Poolside上游429；不保证现时模型/账户可用，不把429写成成功</td></tr><tr><td>微信</td><td>本地授权边界已验证，真实外部扫码及完整绑定登录未完成</td></tr><tr><td>远端/兼容</td><td>此教程应用基线未完成的应用质量CI、required checks/branch protection、MySQL5.7/8.0容器矩阵、独立机器验证仍需单独记录；Pages状态另看公开仓库Actions</td></tr><tr><td>文档站</td><td>必须三份章节组合后构建与浏览器验收；单个内容分支不称完整站点通过</td></tr></tbody></table><p>以上数字只描述旧教程基线，不用于否认顶部当前源码已完成的正式CI与一期组合验收。供应商测试与普通质量冒烟分开。例子中的模型名/响应是契约示意，不复用真实凭据、测试端口、数据库名或用户数据。</p><h2 id="选择部署组合" tabindex="-1">选择部署组合 <a class="header-anchor" href="#选择部署组合" aria-label="Permalink to &quot;选择部署组合&quot;">​</a></h2><p>先读取对应仓库提交和迁移目录，再执行冻结安装/严格测试/实际构建，记录JAR、dist及文档dist的摘要。升级前比对数据库history与目标migration location，按<a href="./upgrade.html">升级</a>准备恢复点；需要功能细节时读<a href="./changelog.html">变更说明</a>。</p><p>若运行环境的行为与本文不一致，首先确认是否是这份代码和产物：旧dist、错API地址、旧数据库或个人配置覆盖都可能使页面看起来“同版本”却不是同一组合。文档不通过修改版本号字符串代替源码配对。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><p>两端<code>pom.xml/package.json</code>、后端<code>system-admin/src/main/resources/db/migration/</code>、相关Controller和服务；前端<code>apps/web-ele/src/router/routes-helper.ts</code>、<code>src/styles/workspace-theme.css</code>及对应测试；质量工具见<a href="./../operations/quality-gates.html">质量门槛</a>。</p>',30)])])}const u=e(o,[["render",i]]);export{b as __pageData,u as default};
